194	export function RunView({
195	  pack,
196	  store,
197	  bench,
198	  remote,
199	}: {
200	  pack: Pack;
201	  /** Where the log lives; the device unless a bench says otherwise. */
202	  store?: RunStore;
203	  /**
204	   * A test run: the pack is being tried, not played. Nothing is saved
205	   * or shared, so the people, race and export panels have nothing to
206	   * hold, and the screen says so with a way back to where the trial began.
207	   */
208	  bench?: { from: string; onLeave: () => void };
209	  /**
210	   * The remote alone, the next move, the last result, undo, as a page
211	   * of its own, for a streaming app's dock. The same controls the floating
212	   * window draws, on a page rather than in a window the browser floats;
213	   * it plays the run like any device, but announces nothing, since the
214	   * page it stands beside does that.
215	   */
216	  remote?: boolean;
217	}) {
218	  const run = useRun(pack, store);
219	  // The dock borrows the floating window's look, which is keyed on the document.
220	  useEffect(() => {
221	    if (!remote) return;
222	    document.documentElement.dataset["pip"] = "controls";
223	    return () => {
224	      delete document.documentElement.dataset["pip"];
225	    };
226	  }, [remote]);
227	
228	  // Sounds for what happens while nobody is looking at the screen. Hooked
229	  // here, before any early return, as hooks must be.
230	  const account = useAccount();
231	  const me = account.status === "signed-in" ? account.user.id : null;
232	  const [alerts, setAlerts] = useAlertSettings();
233	  const [settingsOpen, setSettingsOpen] = useState(false);
234	  const closeSettings = useCallback(() => setSettingsOpen(false), []);
235	  // The controls in a window of their own, for a streamer; see ControlPanel.
